cards.append(compact('you_jiuguo','游救国','游救国原是战乱中南下投亲的青年，一场火车顶上的事故毁掉他的面容，也让别人以为他已经死亡。他挣扎求生时换上死者衣服，因身份证明与日语口音被认作日本军官平地青雄，从此以这个身份治疗、学习并继承医院。被认为因伤失忆之后，他又获忍术高手重新训练，承受衣钵，地位高于廉正风。战地医院里不断出现的伤者使他把个人痛苦扩展成对战争和服从的思考，他逐渐成为内分泌研究专家，试图消除他所称的人性中的奴性。他在鸭群手术与药物试验中取得行为改变，却把动物结果过早外推到人类，在廉正风协助下把大量药物投入蓄水湖，令数百万人未经选择就参与试验。卫观察到的短暂社会反抗是否由药造成仍未证实，更没有持续改变人的能力。他偶然得知陈名富冒用自己的名字，前去看看，最后接受对方道歉并一笔勾销，没有索回其婚姻与一生。终局他拒绝加入勒曼医院，却同意独立研究、每天交流；他理想高远而能越过个人同意的边界，适合演成愿解释、肯合作、也须被追问方法代价的研究者，不能写成一句话自由改造全人类本性的神。','与陈名富和解，与勒曼医院保持各自研究、每日交换意见；人体本性改变仍未成功证实',['主角','阶段性对立者'],'减少战争制造的苦难，寻求让人不再盲从的技术办法','以研究与长篇论证说明动机，也维持忍术和身份隐秘','认为可以造福大量人时可能越过他人知情选择；个人旧账却能宽恕','理想与实证应区分，改变鸭子的效果不能自动保证能永久改变人',[ab('忍术与潜伏','在冒认平地青雄后获最高高手传授，能与廉正风合作隐秘搬运和接近目标','依训练、环境及组织协助，不是幽灵；具体组织秘法未全部展示'),ab('内分泌研究与动物试验','主持医院，研究内分泌与行为，用手术和药物使部分鸭子不再跟随群体','动物手术有死亡，人体效果未知；投水药物不是已证城市级永久精神控制',kind='研究'),ab('身份适应与语言','精通四国口音日语，借失忆解释融入另一身份并长期学习医学','毁容与特定时代误认造就机会，不是随时完美易容')],[ev('129',2015,2058,'平地院长及医学研究地位'),ev('129',2144,2165,'和解与自述意愿'),ev('129',2233,2279,'身份误认、忍术传承和口音'),ev('129',2367,2449,'研究、鸭试验、未同意投药及人体结果不定'),ev('129',2488,2528,'研究仍初步、独立交流协议')],profile='martial',aliases=['平地青雄（院长）','高鬼'],extra={'appearance':{'description':'面部被事故严重毁损，常以面具遮住；高大身形与目光仍有辨识度。','portrayal':'解释痛苦和研究时认真冗长，面对旧名与旧人时先沉默观察。'},'uncertainties':['真正日本军官平地青雄已死，非此卡；其具体死亡原因未明。','药物对城市居民行为的因果、持续时间与副作用没有可靠人体证明。','关于本性和战争的理论属于人物思想及小说设定，不是现实医学结论。']}))
cards.append(compact('chen_mingfu','陈名富','陈名富是贫寒出身的逃难青年，曾在拥挤的火车顶上替邻座扶住网篮。事故之后他保住了装钱和书信的篮子，本意是到目的地报讯、物归原主，然而语言不通使卢家把他直接当成游救国。他见到卢喜鹊后动了真情，明知身份误认仍顺势承认，用不让老人失望来解释自己的选择，同时也知道真正驱使自己的是想留下她。婚后他努力学习、经营银号，在战前转移资金保住事业，后来把银号发展成银行；他爱妻、照顾岳家，数十年生活美满，却没有因此摆脱冒名的压力。他设想过向真正游家长辈坦白并求原谅，也与妻子共同背负秘密，直至她离世都未解除心结。当一张可怕的脸出现在窗外，他以为被自己取代的人从阴间讨债，求助小郭寻找答案，既恐惧又想说明自己并非恶意夺取人生。真正游救国到来后，他叩头道歉，得到一笔勾销的回应，第一次放下长期的重负。角色逻辑应同时保留初始善意、明知而为的欺骗与长期负责的生活，不能用幸福结局取消欺骗，也不能把他的一生简化成贪财骗婚的单一恶人。','已与真正游救国相认并获谅解，妻卢喜鹊已于两年前去世；继续拥有以旧名经营的人生','主角','维护亲手经营的感情与生活，同时希望秘密能被理解而非永远靠隐瞒支撑','善于学习和经营，以具体照料履行家庭责任','身份将被揭穿时恐惧，却愿向真正当事人说明并承担歉意','好的后果不自动抹去不当选择，说明事实需要面对真正受影响的人',[ab('银行经营与风险判断','学习语言、管理银号、在战前转移资金并发展为银行','财富需组织和长期信誉运作，不是个人战斗能力'),ab('长期身份维持','依靠误认、婚姻和日常履责维持游救国身份','不具专业易容或改记忆技能，旧人出现能迅速撼动他的安全感')],[ev('129',106,118,'火车顶帮助邻座'),ev('129',394,429,'报讯本意与误认开始'),ev('129',520,613,'明知冒名、婚姻和银行经营'),ev('129',1995,2006,'恐惧又希望说明'),ev('129',2144,2152,'获谅解与妻已去世'),ev('129',2532,2549,'再度致歉感激与对善意起点的回看')],profile='expert',aliases=['游救国（银行家）'] ))
cards.append(compact('lu_xique','卢喜鹊','卢喜鹊是银号东主卢振中的女儿，年轻时秀丽而大方，不以忸怩掩饰自己的好感。父亲早与游家有婚约之意，临病重时等到持信前来的青年，便把他认作期待已久的女婿；真正站在面前的却是陈名富。她与他迅速相爱并成婚，后来共同继承银号。她的作用不能只写作令男子神魂颠倒的美女：原文明说她学养很好，精通日、英、法文，是城市大学的高材生，与陈名富建立了持续数十年的恩爱生活。她知道伴侣冒名所带来的秘密压力，与他共同担忧真正当事人归来，而不是永远被蒙在鼓里的无意识奖品。夫妻没有子女，她在故事发生前两年安然去世，临终仍未放下这块心头大石，因此没有亲自见到后来和解。陈名富最深的遗憾之一，就是不能把原主愿意一笔勾销的消息告诉她。终局演绎可以让这份未完成的安心成为人物愿望，却不能把陈名富关于她必定原谅的预想当成她对任何谎言都无条件容忍。她对人的选择有自己的感情、知识和判断，婚约与冒名不应替她消除表达真实意愿的机会。','故事前两年已去世，生前知丈夫秘密并为之忧虑；未亲见后来的和解','主角','维持亲密而诚实的生活，让所爱之人能摆脱长期恐惧','大方表达好感，以语言知识和学养参与交流，不把柔和等同于无主见','关系中的秘密威胁安定时会忧虑，也会与伴侣共同承受','她爱的是相处中的人，但这不等于所有欺瞒都可由旁人替她接受',[ab('语言与学养','熟悉日语、英语、法语，受大学教育','无专业情报或战斗展示，不因多语就默认能解所有密文'),ab('关系维系','与丈夫保持数十年恩爱，理解并共同承担秘密压力','感情不能自动替另一人取得身份权，也不能免除死亡与未知')],[ev('129',492,558,'初见与自我介绍、性格风貌'),ev('129',575,600,'长期婚姻、去世及学养'),ev('129',2144,2152,'丈夫遗憾她未见和解，二人共负秘密')],profile='expert',extra={'version':{'basis':'已死人物显式恢复最后能独立生活的成年形态参演','canonical_endpoint':'两年前去世，未亲见真游救国原谅陈名富','deployment':'恢复生前最后可独立生活的身体，终局和解作为新获知消息；无复活他人或改身份能力。'},'adaptations':[{'change':'恢复最后可独立生活的成年形态，并允许获知晚于生前的和解。','reason':'将未完成的安心与关系选择转化为演绎空间。','power_impact':'仅参演恢复，不新增超常能力。'}]}))
